// STAGE 1 — deterministic pre-filter. Runs BEFORE the model, so obvious junk
// costs nothing and never depends on LLM judgement.
// ---- TUNE THESE TWO LISTS ----
const VIP_SENDERS = [
  // 'chairman@board.example.com',
  // 'keyclient@example.com',
];
const BLOCK_LABELS = ['SPAM', 'TRASH', 'CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL'];
// -------------------------------

const j = $json;
const from = (j.from || '').toLowerCase();
const labels = Array.isArray(j.label_ids) ? j.label_ids : [];

let verdict = 'read';
let reason = '';

if (VIP_SENDERS.some((v) => v && from.includes(v.toLowerCase()))) {
  // VIP always wins, even if Gmail mislabelled it.
  verdict = 'read';
  reason = 'VIP sender — bypassed all filters';
} else {
  const hit = labels.filter((l) => BLOCK_LABELS.includes(l));
  if (hit.length) {
    verdict = 'skip';
    reason = `Gmail label: ${hit.join(', ')}`;
  } else if (j.has_unsubscribe) {
    verdict = 'skip';
    reason = 'Bulk mail (List-Unsubscribe / List-Id header)';
  } else if (/(no-?reply|do-?not-?reply|mailer-daemon|postmaster)@/i.test(from)) {
    verdict = 'skip';
    reason = 'Automated no-reply sender';
  }
}

return { json: { ...j, prefilter_verdict: verdict, prefilter_reason: reason } };

