// The model returns JSON as text. Parse defensively — malformed output must not
// crash the flow, and must not silently produce an empty reply.
const src = $('Pre-Filter (Deterministic)').first().json;
const raw = ($input.first().json.text ?? $input.first().json.response ?? '').toString();

let p = {};
let parseError = false;
try {
  const cleaned = raw.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
  p = JSON.parse(cleaned);
} catch (e) {
  parseError = true;
  p = {};
}

const allowed = ['high', 'normal', 'low', 'noise'];
let importance = allowed.includes(p.importance) ? p.importance : null;

// Fail LOUD, not silent: if we could not read the model's verdict we surface the
// email rather than dropping it. Never let a parse failure suppress real mail.
if (importance === null) {
  importance = 'normal';
  parseError = true;
}

return [{
  json: {
    ...src,
    importance,
    category: p.category ?? '(unclassified)',
    needs_reply: p.needs_reply === true,
    summary: parseError
      ? 'PARSE FAILED — could not read the model verdict. Surfacing this email anyway. Raw output below.'
      : (p.summary ?? '(none)'),
    suggested_reply: p.suggested_reply ?? (parseError ? raw.slice(0, 1500) : ''),
    injection_detected: p.injection_detected === true,
    parse_error: parseError,
  },
}];

